import numpy as np

def step(lam,r,s):
    # polynomial orthog using QR monomials scaled
    t=(lam-lam.mean())/(lam.max()-lam.min())
    Q=np.linalg.qr(r[:,None]*np.vander(t,s+1,increasing=True))[0]
    # residual direction Q_s times sign normalized at zero
    p=np.linalg.lstsq(np.vander(t,s+1,increasing=True),Q[:,-1]/r,rcond=None)[0]
    sign=np.sign(np.polynomial.polynomial.polyval(-lam.mean()/(lam.max()-lam.min()),p))
    return Q[:,-1]*sign

if __name__=='__main__':
 rng=np.random.default_rng(52)
 for s in (2,3,4):
  best=(0,None)
  for j in range(60):
   n=s+2+rng.integers(0,6)
   lam=np.sort(rng.uniform(1,20,n));r=rng.normal(size=n);r/=np.linalg.norm(r)
   hist=[]
   for k in range(1500):
    r=step(lam,r,s)
    if k>1480: hist.append(r.copy())
   diff=max(np.linalg.norm(hist[i]-hist[i-2]) for i in range(2,len(hist)))
   if diff>best[0]:best=(diff,(lam,r))
  print(s,best,flush=True)

