 v=U[:,0]/np.sqrt(-ev[0])+U[:,1]/np.sqrt(ev[1]);u=np.linalg.pinv(A)@v;k=null_space(A)[:,0]
 for a in [-2,-1,0,1,2]:
  x=np.r_[np.zeros(2),u+a*k];f=field(x)
  print(a,nullfunc(x),deriv(nullfunc,x,f))

